const items = $input.all();

return items.map(item => {
  const data = item.json;

  // 1. Customer type
  const customerTag = String(
    data["customer tag"] || ""
  ).toLowerCase();

  const isOldCustomer = customerTag.includes("old");
  const isNewCustomer = customerTag.includes("new");

  // 2. Country detection
  const country = String(
    data.country ||
    data.Country ||
    data.data?.person?.country ||
    data.data?.company?.country ||
    data.fields?.Country ||
    ""
  ).toLowerCase().trim();

  const targetCountries = [
    "us",
    "usa",
    "united states",
    "united states of america",
    "india",
    "uk",
    "united kingdom",
    "great britain"
  ];

  const isTargetCountry = targetCountries.includes(country);

  // 3. Software industry detection
  const companyInfo = [
    data.industry,
    data.Industry,
    data.data?.company?.industry,
    data.data?.company?.description,
    data["company name "],
    data["Company Name"],
    data.company,
    data.website
  ].filter(Boolean).join(" ").toLowerCase();

  const softwareKeywords = [
    "software",
    "saas",
    "technology",
    "tech",
    "it services",
    "information technology",
    "software development",
    "computer software"
  ];

  const isSoftware = softwareKeywords.some(keyword =>
    companyInfo.includes(keyword)
  );

  // 4. Calculate score
  let netScore = 0;
  const reasons = [];

  if (isOldCustomer) {
    netScore += 1;
    reasons.push("Old customer +1");
  }

  if (isTargetCountry) {
    netScore += 1;
    reasons.push("Target country +1");
  }

  if (isSoftware) {
    netScore += 1;
    reasons.push("Software company +1");
  }

  // New customers receive no automatic bonus.
  // New US software customer = 2 points.

  // 5. Lead classification
  let leadCategory;
  let referredTo;

  if (netScore === 3) {
    leadCategory = "Premium";
    referredTo = "Manager";
  } else if (netScore === 1 || netScore === 2) {
    leadCategory = "Good";
     // leadCategory = "Premium";
    referredTo = "Sales Head";
  } else {
    // leadCategory = "Good";
   leadCategory = "Low priority";
    referredTo = "Google Sheets Only";
  }

  // 6. Return original data and scoring fields
  return {
    json: {
      ...data,
      isOldCustomer,
      isNewCustomer,
      detectedCountry: country || "Unknown",
      isTargetCountry,
      isSoftware,
      netScore,
      scoreReasons: reasons.join(", ") || "No qualifying conditions",
      leadCategory,
      referredTo,
      leadStatus: netScore > 0 ? "Qualified" : "Unqualified"
    }
  };
});
